from fastapi import FastAPI
from pydantic import BaseModel

app = FastAPI()

class Query(BaseModel):
    text: str

@app.post("/predict")
def predict(q: Query):
    return {"label": "positive" if "good" in q.text else "negative"}   # call your model here
